const text = params.text || params.input || '';
if (!text) throw new Error('params.text required');
const chars_total = text.length;
const chars_no_ws = text.replace(/\s/g, '').length;
const lines = text.split('\n');
const lines_count = lines.length;
const lines_non_empty = lines.filter(l => l.trim()).length;
const words_arr = text.match(/[\w\u00C0-\u024F\u4e00-\u9fff\u3040-\u30ff]+/g) || [];
const words_count = words_arr.length;
const cjk = text.match(/[\u4e00-\u9fff\u3040-\u30ff\uac00-\ud7af]/g) || [];
const cjk_count = cjk.length;
// Word frequency (top N)
const freq = {};
for (const w of words_arr) { const k = w.toLowerCase(); freq[k] = (freq[k] || 0) + 1; }
const topN = Number(params.top_words ?? 10);
const top_words = Object.entries(freq).sort((a, b) => b[1] - a[1]).slice(0, topN).map(([word, count]) => ({ word, count }));
// Reading time estimate (200 wpm for English, 300 cpm for CJK)
const en_words = words_count - cjk_count;
const minutes = en_words / 200 + cjk_count / 300;
// Language heuristic
let language = 'unknown';
if (cjk_count > chars_total * 0.3) language = 'cjk';
else if (/[\u0400-\u04ff]/.test(text)) language = 'cyrillic';
else if (/[\u0590-\u05ff]/.test(text)) language = 'hebrew';
else if (/[\u0600-\u06ff]/.test(text)) language = 'arabic';
else if (/^[\x00-\x7f\s]*$/.test(text.slice(0, 1000))) language = 'ascii/latin';
return { chars_total, chars_no_ws, lines: lines_count, lines_non_empty, words: words_count, cjk_chars: cjk_count, top_words, reading_minutes: Number(minutes.toFixed(1)), language };
